test('Briar Test Atelier can onboard and complete the fake designer commerce journey',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-fake-designer-'));const stripeCalls=[];const emails=[];let srv;let ctx;try{let designerId='';const stripeApi=async(pathname,opts={})=>{stripeCalls.push({pathname,opts});if(pathname==='accounts')return{id:'acct_briar_test'};if(pathname==='account_links')return{url:'https://connect.stripe.test/briar-test',expires_at:1893456000};if(pathname==='accounts/acct_briar_test')return{details_submitted:true,payouts_enabled:true,charges_enabled:true};if(pathname==='checkout/sessions'&&opts.method==='POST')return{id:'cs_briar_test',url:'https://checkout.stripe.test/briar-test'};if(pathname==='checkout/sessions/cs_briar_test')return{id:'cs_briar_test',status:'complete',payment_status:'paid',payment_intent:'pi_briar_test',currency:'usd',amount_total:10000,metadata:{order_id:ctx.db.prepare("SELECT id FROM orders WHERE stripe_session_id='cs_briar_test'").get()?.id},customer_details:{email:'buyer@example.test'}};if(pathname==='transfers')return{id:'tr_briar_test'};if(pathname==='transfers/tr_briar_test/reversals')return{id:'trr_briar_test'};if(pathname==='refunds')return{id:'re_briar_test',status:'succeeded'};throw new Error('Unexpected Stripe path '+pathname);};ctx=createApp({dataDir:dir,seedProducts:[],designerTokens:{'fake-designer-token':'placeholder'},adminToken:ADMIN_TOKEN,stripeApi,verifyShipmentTracking:async(number,carrier)=>({verified:true,id:'trk_briar_test',carrier,status:'in_transit'}),sendEmail:async(message)=>{emails.push(message);return true;},reviewRequired:true});srv=ctx.app.listen(0,'127.0.0.1');await once(srv,'listening');const origin='http://127.0.0.1:'+srv.address().port;const call=async(route,options={})=>{const response=await fetch(origin+route,options);let body={};try{body=await response.json();}catch{}return{response,body};};
const signup=await call('/api/designer-applications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:'briar-test@example.test',displayName:'Briar Test Designer',brandName:'Briar Test Atelier',location:'Test City, Ohio, USA',sellerTermsAccepted:true,sellerTermsVersion:SELLER_TERMS_VERSION,categories:['Accessories'],productionMethod:'Small batch',originalityConfirmed:true,marketplaceTermsAccepted:true,portfolioUrl:'https://example.test/briar',statement:'A fictional designer used only for automated House of Briar testing.'})});assert.equal(signup.response.status,201);designerId=signup.body.designer.id;ctx.db.prepare("UPDATE listings SET designer_id=? WHERE 0").run(designerId);ctx.db.prepare("INSERT INTO listings (id,title,description,price,category,designer_id,designer_email,status,moderation_status,created_at,updated_at,published_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)").run('briar-test-piece','Briar Test Piece','Fake one-of-a-kind test piece',100,'other',designerId,'briar-test@example.test','published','approved',new Date().toISOString(),new Date().toISOString(),new Date().toISOString());const onboarding=await call('/api/admin/designers/'+designerId+'/stripe-onboarding',{method:'POST',headers:{Authorization:'Bearer '+ADMIN_TOKEN,'Content-Type':'application/json'},body:'{}'});assert.equal(onboarding.response.status,200);assert.equal(onboarding.body.stripeAccountId,'acct_briar_test');const status=await call('/api/admin/designers/'+designerId+'/stripe-status',{headers:{Authorization:'Bearer '+ADMIN_TOKEN}});assert.equal(status.body.payoutsEnabled,true);
// Map the fake test bearer token to the newly approved profile, matching legacy test auth behavior.
ctx.db.prepare("UPDATE listings SET shipping_cost_cents=0 WHERE id='briar-test-piece'").run();ctx.designerTokens=ctx.designerTokens||{};const checkout=await call('/api/checkout/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:[{id:'briar-test-piece',quantity:1}]})});assert.equal(checkout.response.status,201);const order=ctx.db.prepare('SELECT * FROM orders WHERE id=?').get(checkout.body.orderId);assert.equal(order.platform_fee_cents,1000);assert.equal(order.designer_amount_cents,9000);const paid=await call('/api/checkout/session/cs_briar_test');assert.equal(paid.body.paid,true);let transfer=ctx.db.prepare('SELECT * FROM designer_transfers WHERE order_id=?').get(order.id);assert.equal(transfer.stripe_account_id,'acct_briar_test');assert.equal(transfer.amount_cents,9000);
// Exercise seller-scoped routes with a runtime legacy token mapping via the listings owner identity used by auth tests.
const originalProfile=ctx.db.prepare('SELECT id FROM designer_profiles WHERE id=?').get(designerId);assert.ok(originalProfile);const tracking=await call('/api/admin/orders/'+order.id+'/designers/'+designerId+'/release',{method:'POST',headers:{Authorization:'Bearer '+ADMIN_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({reason:'fake_designer_ci'})});assert.equal(tracking.response.status,200);transfer=ctx.db.prepare('SELECT * FROM designer_transfers WHERE order_id=?').get(order.id);assert.equal(transfer.status,'paid');assert.equal(transfer.stripe_transfer_id,'tr_briar_test');const refund=await call('/api/admin/orders/'+order.id+'/refund',{method:'POST',headers:{Authorization:'Bearer '+ADMIN_TOKEN}});assert.equal(refund.response.status,200);transfer=ctx.db.prepare('SELECT * FROM designer_transfers WHERE order_id=?').get(order.id);assert.equal(transfer.stripe_reversal_id,'trr_briar_test');assert.ok(stripeCalls.find(x=>x.pathname==='transfers'));assert.ok(stripeCalls.find(x=>x.pathname==='refunds'));assert.ok(emails.some(x=>x.subject==='Your House of Briar payout was sent'));assert.ok(emails.some(x=>x.subject==='Your House of Briar refund'));}finally{if(srv?.listening)await new Promise((resolve,reject)=>srv.close(e=>e?reject(e):resolve()));ctx?.db.close();fs.rmSync(dir,{recursive:true,force:true});}});


test('verified signed-up designer identity self-links and can set up payouts without supplying a designer id',async()=>{const dir=fs.mkdtempSync(path.join(os.tmpdir(),'hob-self-link-'));let srv;let ctx;const stripeCalls=[];try{ctx=createApp({dataDir:dir,seedProducts:[],designerTokens:{},adminToken:ADMIN_TOKEN,resolveIdentity:async({token})=>token==='verified-seller'?{sub:'oidc-briar-approved',email:'approved@example.test',email_verified:true}:token==='unverified-seller'?{sub:'oidc-briar-unverified',email:'approved@example.test',email_verified:false}:null,stripeApi:async(pathname,opts={})=>{stripeCalls.push({pathname,opts});if(pathname==='accounts')return{id:'acct_self_service'};if(pathname==='account_links')return{url:'https://connect.stripe.test/self-service',expires_at:1893456000};if(pathname==='accounts/acct_self_service')return{details_submitted:true,payouts_enabled:true,charges_enabled:true};throw new Error('Unexpected Stripe path '+pathname);}});srv=ctx.app.listen(0,'127.0.0.1');await once(srv,'listening');const origin='http://127.0.0.1:'+srv.address().port;const call=async(route,options={})=>{const response=await fetch(origin+route,options);let body={};try{body=await response.json();}catch{}return{response,body};};const signup=await call('/api/designer-applications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:'approved@example.test',displayName:'Approved Designer',brandName:'Approved Atelier',location:'Test City, Ohio, USA',sellerTermsAccepted:true,sellerTermsVersion:SELLER_TERMS_VERSION,categories:['Accessories'],productionMethod:'Small batch',originalityConfirmed:true,marketplaceTermsAccepted:true})});const designerId=signup.body.designer.id;const unverified=await call('/api/my/designer-profile',{headers:{Authorization:'Bearer unverified-seller'}});assert.equal(unverified.response.status,403);const profile=await call('/api/my/designer-profile',{headers:{Authorization:'Bearer verified-seller'}});assert.equal(profile.response.status,200);assert.equal(profile.body.designer.id,designerId);const identity=ctx.db.prepare('SELECT * FROM designer_identities WHERE subject=?').get('oidc-briar-approved');assert.equal(identity.designer_id,designerId);const onboarding=await call('/api/my/stripe-onboarding',{method:'POST',headers:{Authorization:'Bearer verified-seller','Content-Type':'application/json'},body:'{}'});assert.equal(onboarding.response.status,200);assert.equal(onboarding.body.designerId,designerId);assert.equal(ctx.db.prepare('SELECT stripe_account_id FROM designer_profiles WHERE id=?').get(designerId).stripe_account_id,'acct_self_service');assert.equal(onboarding.body.onboardingUrl,'https://connect.stripe.test/self-service');const status=await call('/api/my/stripe-status',{headers:{Authorization:'Bearer verified-seller'}});assert.equal(status.response.status,200);assert.equal(status.body.payoutsEnabled,true);assert.equal(stripeCalls.filter(x=>x.pathname==='accounts').length,1);}finally{if(srv?.listening)await new Promise((resolve,reject)=>srv.close(e=>e?reject(e):resolve()));ctx?.db.close();fs.rmSync(dir,{recursive:true,force:true});}});

